const ImageKit = require("@imagekit/nodejs").default;

const imagekit = new ImageKit({
  privateKey: process.env.IMAGEKIT_PRIVATE_KEY,
});

const getSignedImageUrl = (fileName, expiresIn = 300) => {
  if (!fileName) return null;

  const urlEndpoint = process.env.IMAGEKIT_BASE_URL;

  if (!urlEndpoint) {
    throw new Error("IMAGEKIT_BASE_URL is not configured");
  }

  // Stored filenames are generated by our backend.
  return imagekit.helper.buildSrc({
    urlEndpoint,
    src: `/${fileName}`,
    signed: true,
    expiresIn,
  });
};

module.exports = {
  getSignedImageUrl,
};
